/* 
  Conceptual Session Auth Flow in Next.js 
*/

export async function getSession(request) {
  // 1. Read the meaningless string from the cookie
  const sessionId = request.cookies.get('session_id');
  if (!sessionId) return null;

  // 2. STATEFUL OPERATION: We MUST query the database!
  // This proves the session wasn't revoked by an admin.
  const session = await db.sessions.findUnique({
    where: { id: sessionId },
    include: { user: true }
  });

  // 3. Return the actual user data found in the DB
  return session?.user;
}
